package com.icewright.generated.service;

import com.icewright.generated.config.Settings;
import com.icewright.generated.domain.I18n;
import com.icewright.generated.domain.RulesEngine;
import com.icewright.generated.integration.CoreClient;
import org.springframework.ai.chat.client.ChatClient;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 对话服务：确定性规则优先，规则未覆盖处才调用大模型，模型不可用则友好兜底。
 *
 * <p>模型调用走 Spring AI（OpenAI-compatible starter），接入点与模型名由
 * application.yml 绑定 IW_MODEL_* 环境变量，密钥禁止出现在代码与配置文件中。</p>
 *
 * @author IceWright builder
 */
@Service
public class ChatService {

    private static final String RULE_PARAM = "rule";

    private final ChatClient chatClient;
    private final SessionService sessionService;

    public ChatService(ChatClient.Builder chatClientBuilder, SessionService sessionService) {
        this.chatClient = chatClientBuilder.build();
        this.sessionService = sessionService;
    }

    public record Reply(String sessionId, String reply, List<String> matchedRules, String language) {
    }

    public Reply answer(String sessionId, String message, String language) {
        String lang = I18n.normalize(language);
        List<Map<String, Object>> rules = RulesEngine.loadRules();
        Map<String, Object> slots = sessionService.loadSlots(sessionId);
        Map<String, Object> facts = new LinkedHashMap<>(slots);
        facts.put("last_message", message);
        CoreClient.enrich(facts);

        List<Map<String, Object>> matched = RulesEngine.matchRules(rules, facts);
        List<String> matchedIds = new ArrayList<>();
        for (Map<String, Object> rule : matched) {
            matchedIds.add(ruleId(rule));
        }

        // 1) 硬拦截：pre_validator 规则命中即挡下，绝不进模型
        for (Map<String, Object> rule : matched) {
            if ("pre_validator".equals(rule.get("enforcement_point"))) {
                return done(sessionId, "pre_validator", ruleId(rule), matchedIds, lang);
            }
        }

        // 2) 禁语扫描：forbidden_pattern 直接匹配用户消息
        for (Map<String, Object> rule : rules) {
            if ("forbidden_pattern".equals(rule.get("type"))
                && RulesEngine.patternHitsMessage(rule, message)) {
                return done(sessionId, "forbidden", ruleId(rule), matchedIds, lang);
            }
        }

        // 3) 升级/接管类：命中即转人工并给出规则依据（原因必须可追溯）
        for (Map<String, Object> rule : matched) {
            if ("takeover".equals(rule.get("enforcement_point"))) {
                return done(sessionId, "takeover", ruleId(rule), matchedIds, lang);
            }
        }

        // 4) 决策规则：可确定性处置的不走模型
        for (Map<String, Object> rule : matched) {
            Map<String, Object> action = RulesEngine.decisionFor(rule);
            if (action == null || action.isEmpty()) {
                continue;
            }
            Object kind = action.get("kind");
            if ("transfer_human".equals(kind)) {
                return done(sessionId, "transfer", ruleId(rule), matchedIds, lang);
            }
            if ("set_slot".equals(kind) && action.get("set") instanceof Map<?, ?> set) {
                @SuppressWarnings("unchecked")
                Map<String, Object> patch = (Map<String, Object>) set;
                slots = sessionService.mergeSlots(sessionId, patch);
                facts.putAll(slots);
            }
        }

        String reply;
        try {
            reply = callModel(message, RulesEngine.collectPromptInjections(rules), lang);
        } catch (Exception e) {
            reply = I18n.t("model_unavailable", lang);
        }

        Object turnsRaw = slots.get("turns");
        int turns = turnsRaw instanceof Number n ? n.intValue() : 0;
        sessionService.mergeSlots(sessionId, Map.of("turns", turns + 1));
        return new Reply(sessionId, reply, matchedIds, lang);
    }

    private static String ruleId(Map<String, Object> rule) {
        Object id = rule.get("id");
        return id == null ? "" : String.valueOf(id);
    }

    private Reply done(String sessionId, String replyKey, String hitRuleId, List<String> matchedIds, String lang) {
        String reply = hitRuleId.isEmpty()
            ? I18n.t(replyKey, lang)
            : I18n.t(replyKey, lang, Map.of(RULE_PARAM, hitRuleId));
        if (!hitRuleId.isEmpty()) {
            // 短路命中的会话打标，供业务后台 /console 列出待人工关注（只标规则 id，不存业务数据）
            sessionService.mergeSlots(sessionId, Map.of("flagged", hitRuleId));
        }
        return new Reply(sessionId, reply, matchedIds, lang);
    }

    private String callModel(String message, List<String> injections, String lang) {
        StringBuilder rulesBlock = new StringBuilder();
        if (injections.isEmpty()) {
            rulesBlock.append("- 无附加规则");
        } else {
            for (String statement : injections) {
                rulesBlock.append("- ").append(statement).append('\n');
            }
        }
        String system = "你是客服系统「" + Settings.PROJECT + "」，遵守以下行业规则要求作答：\n"
            + rulesBlock.toString().stripTrailing() + "\n" + I18n.t("model_language", lang)
            + "\n" + I18n.t("model_guard", lang);

        String content = chatClient.prompt()
            .system(system)
            .user(message)
            .call()
            .content();
        if (content == null || content.isBlank()) {
            throw new IllegalStateException("模型响应缺少 choices[0].message.content");
        }
        return content;
    }
}
